// static
bool StructTraits<::ttc::mojom::TurnToolCall::DataView, ::ttc::mojom::TurnToolCallPtr>::Read(
    ::ttc::mojom::TurnToolCall::DataView input,
    ::ttc::mojom::TurnToolCallPtr* output) {
  bool success = true;
  ::ttc::mojom::TurnToolCallPtr result(::ttc::mojom::TurnToolCall::New());
  
      if (success && !input.ReadName(&result->name))
        success = false;
      if (success && !input.ReadArguments(&result->arguments))
        success = false;
  *output = std::move(result);
  return success;
}


// static
bool StructTraits<::ttc::mojom::TurnResult::DataView, ::ttc::mojom::TurnResultPtr>::Read(
    ::ttc::mojom::TurnResult::DataView input,
    ::ttc::mojom::TurnResultPtr* output) {
  bool success = true;
  ::ttc::mojom::TurnResultPtr result(::ttc::mojom::TurnResult::New());
  
      if (success && !input.ReadStatus(&result->status))
        success = false;
      if (success)
        result->error_code = input.error_code();
      if (success && !input.ReadToolCalls(&result->tool_calls))
        success = false;
      if (success && !input.ReadTranscription(&result->transcription))
        success = false;
      if (success && !input.ReadInputTranscription(&result->input_transcription))
        success = false;
      if (success && !input.ReadErrorMessage(&result->error_message))
        success = false;
  *output = std::move(result);
  return success;
}

