void HarnessPageHandlerAsyncWaiter::StartSession(
    bool* out_success) {
  base::RunLoop loop;
  proxy_->StartSession(
      base::BindOnce(
          [](base::RunLoop* loop,
             bool* out_success
,
             bool success) {*out_success = std::move(success);
            loop->Quit();
          },
          &loop,
          out_success));
  loop.Run();
}

bool HarnessPageHandlerAsyncWaiter::StartSession(
    ) {
  bool async_wait_result;
  StartSession(&async_wait_result);
  return async_wait_result;
}

